async function viewActe(e){const[a,t,n,s]=await Promise.all([api("/documents"),api("/family/members"),api("/vehicles"),api("/properties")]),d=today(),i=[["",tr("Family (general)")],...t.map(e=>["user:"+e.id,tr("Person")+": "+e.name]),...n.map(e=>["vehicle:"+e.id,tr("Vehicle")+": "+e.name]),...s.map(e=>["property:"+e.id,tr("Property")+": "+e.name])],l=a.filter(e=>e.expiry_date).map(e=>({d:e,days:Math.ceil((new Date(e.expiry_date)-new Date(d))/864e5)})).filter(e=>e.days<=60).sort((e,a)=>e.days-a.days);e.innerHTML=`${subnav("acte")}<div class="pagehead"><div><h1>Acte</h1><p>ID cards, passports, certificates, talon auto, contracts — linked to a person, vehicle or property, with expiry reminders and scans.</p></div></div>\n    ${l.length?`<div class="card" style="margin-bottom:16px"><h3 style="margin-top:0">${tr("Expiring soon")}</h3>\n      <div class="dchips">${l.map(({d:e,days:a})=>`<span class="dchip ${daysClass(a)}">${esc(e.name)} <b>${daysLabel(a)}</b> <span class="dchip-d">${fdate(e.expiry_date)}</span></span>`).join("")}</div></div>`:""}\n    ${canWrite()?addBox("Add document",`<form id="docform" class="formgrid">\n      <div><label>Name</label><input name="name" placeholder="Carte de identitate, Pasaport…" required></div>\n      <div><label>Series / number</label><input name="number" placeholder="optional"></div>\n      <div><label>Belongs to</label><select name="link">${i.map(([e,a])=>`<option value="${e}">${esc(a)}</option>`).join("")}</select></div>\n      <div><label>Expiry date</label><input name="expiry_date" type="date"></div>\n      <div><label>Notes</label><input name="notes" placeholder="optional"></div>\n      <div><label>Scan (PDF or photo)</label><input name="file" type="file" accept=".pdf,image/*"></div>\n      <button class="btn">Add document</button></form>`):""}\n    <div class="card" style="margin-top:16px">\n      ${a.length?`<table class="cards actelist"><thead><tr><th>Document</th><th>Belongs to</th><th>Expires</th><th>Scan</th><th></th></tr></thead><tbody>\n        ${a.map(e=>{let a='<span class="muted">—</span>';if(e.expiry_date){const t=Math.ceil((new Date(e.expiry_date)-new Date(d))/864e5);a=`<span class="${t<0?"badge late":t<=14?"badge unpaid":""}">${fdate(e.expiry_date)} · ${daysLabel(t)}</span>`}return`<tr>\n            <td><b>${esc(e.name)}</b>${e.number?` <span class="muted">${esc(e.number)}</span>`:""}${e.notes?`<br><span class="muted">${esc(e.notes)}</span>`:""}</td>\n            <td class="lowpri" data-label="${tr("Belongs to")}">${(e=>e.person_name?`${tr("Person")}: ${esc(e.person_name)}`:e.vehicle_name?`${tr("Vehicle")}: ${esc(e.vehicle_name)}`:e.property_name?`${tr("Property")}: ${esc(e.property_name)}`:tr("Family"))(e)}</td>\n            <td data-label="${tr("Expires")}">${a}</td>\n            <td class="lowpri" data-label="${tr("Scan")}">${e.attachment?`<a href="/api/documents/${e.id}/attachment" target="_blank">view</a>`:canWrite()?`<label class="btn ghost small" style="display:inline-block">attach<input type="file" data-attach="${e.id}" accept=".pdf,image/*" hidden></label>`:"—"}</td>\n            <td class="right">${canWrite()?`<button class="btn danger small" data-del="${e.id}">Delete</button>`:""}</td>\n          </tr>`}).join("")}</tbody></table>`:'<div class="empty"><b>No acte yet</b>Add ID cards, passports and other documents — the ones with an expiry date show up in reminders and alerts.</div>'}\n    </div>`,$("#docform")?.addEventListener("submit",async a=>{a.preventDefault();const t=a.target,n=Object.fromEntries(new FormData(t)),s={name:n.name,number:n.number,expiry_date:n.expiry_date,notes:n.notes};if(n.link){const[e,a]=n.link.split(":");s[e+"_id"]=Number(a)}const d=t.querySelector('input[name="file"]'),i=d?.files?.[0];try{const a=await api("/documents",{method:"POST",body:s});if(i){const t=new FormData;t.append("file",i);try{await api(`/documents/${a.id}/attachment`,{method:"POST",body:t})}catch(a){return toast(tr("Document saved, but the scan failed:")+" "+a.message),void viewActe(e)}}toast("Document added"),viewActe(e)}catch(e){toast(e.message)}}),e.querySelectorAll("[data-del]").forEach(a=>a.onclick=async()=>{await askDelete({en:"document",ro:"documentul",name:rowName(a),detailEn:"Its scan is deleted too.",detailRo:"Se șterge și scanarea."})&&(await api("/documents/"+a.dataset.del,{method:"DELETE"}),viewActe(e))}),e.querySelectorAll("[data-attach]").forEach(a=>a.onchange=async()=>{const t=new FormData;t.append("file",a.files[0]);try{await api(`/documents/${a.dataset.attach}/attachment`,{method:"POST",body:t}),toast("Scan attached"),viewActe(e)}catch(e){toast(e.message)}})}